function createBlocks() {
  // Mark all grid spots as available ("free")
  for (let i = 0; i < numGrid; i++) {
    blockInfo[i] = { type: "free" };
  }

  for (let i = 0; i < numGrid; i++) {
    let block = new Block(i, blockInfo);
    blocks[i] = block;
  }
}

function drawBlocks() {
  for (let b of blocks) {
    b.draw();
  }
}

class Block {
  constructor(i, blockInfo) {
    this.i = i;
    this.type = blockInfo[i].type;
    this.taken = false;

    if (this.type == "free") {
      this.col = i % numCols;
      this.row = int(i / numCols);
      this.x = margin + this.col * (colWidth+gap);
      this.y = margin + this.row * (rowHeight+gap);
      this.w = colWidth;
      this.h = rowHeight;
      this.neighbourIndices = [];

      // Kies willekeurig een type
      this.type = random(["single", "top", "down", "four"]);

      if (this.type == "top") {
        let neighbourCol = this.col + 1;
        let neighbourRow = this.row;
        this.color = random(main[0]);
        if (neighbourCol >= numCols) {
          this.type = "single";
        } else {
          let ni = neighbourRow * numCols + neighbourCol;
          if (blockInfo[ni].type === "free") {
            this.neighbourIndices.push(ni);
            blockInfo[ni].type = "taken";
            this.w = colWidth * 2 + gap;
          } else {
            this.type = "single";
          }
        }
      }

      if (this.type == "down") {
        let neighbourCol = this.col;
        let neighbourRow = this.row + 1;
        this.color = random(main[2]);
        if (neighbourRow >= numRows) {
          this.type = "single";
        } else {
          let ni = neighbourRow * numCols + neighbourCol;
          if (blockInfo[ni].type === "free") {
            this.neighbourIndices.push(ni);
            blockInfo[ni].type = "taken";
            this.h = rowHeight * 2 + gap;
          } else {
            this.type = "single";
          }
        }
      }

      if (this.type == "four") {
        let neighbourCol = this.col + 1;
        let neighbourRow = this.row + 1;
        this.color = random(main[1]);

        let nb1 = this.row * numCols + neighbourCol;
        let nb2 = neighbourRow * numCols + this.col;
        let nb3 = neighbourRow * numCols + neighbourCol;

        if (
          neighbourCol >= numCols ||
          neighbourRow >= numRows ||
          blockInfo[nb1].type !== "free" ||
          blockInfo[nb2].type !== "free" ||
          blockInfo[nb3].type !== "free"
        ) {
          this.type = "single";
        } else {
          this.neighbourIndices.push(nb1, nb2, nb3);
          blockInfo[nb1].type = "taken";
          blockInfo[nb2].type = "taken";
          blockInfo[nb3].type = "taken";
          this.w = colWidth * 2 + gap;
          this.h = rowHeight * 2 + gap;
        }
      }

			if (this.type === "single") {
        this.color = random(main[3]);
      }

    }
  }

  draw() {
    if (this.type !== "taken") {
      fill(this.color);
      noStroke();
      rect(this.x, this.y, this.w - gap, this.h - gap);

      // Debug: teken type-naam in het vak
      // noStroke();
      // fill(0, 0, 50, 100); // grijs
      // textSize(8);
      // textAlign(CENTER, CENTER);
      // text(this.type, this.x + this.w / 2, this.y + this.h / 2);
    }
  }
}


