let szw = 2800;
let szh = 700;
let numCols = 160;
let numRows = 40;
let colWidth, rowHeight, numGrid;
let gap = 2;
let margin = 20;
let strokeWeight = 1;

let blocks = [];
let blockInfo = [];

function setup() {
  createCanvas(szw, szh);
  colorMode(HSB, 360, 100, 100, 100);
  pixelDensity(1);
  noStroke();
  angleMode(DEGREES);
  colWidth = (szw - margin * 2 - gap*(numCols-1)) / numCols;
  rowHeight = (szh - margin * 2 - gap*(numRows-1)) / numRows;
  numGrid = numCols * numRows;

  createBlocks();
  background("#DCDCDC");
  drawBlocks();
  noLoop();
}

